"""
Named errors for the state machines' Retry rules.

Lambdas run by a state machine do not retry; the state machine does, and it can only retry an error it
can name. Step Functions names a Lambda error after the exception's class. Transient AWS errors (throttling,
AWS-side failures, connection problems) therefore leave a Lambda as AWSTransientError, and every other
error keeps its own name and is not retried.
"""

import functools

import botocore.exceptions


class AWSTransientError(Exception):
    """An AWS call was throttled, failed on the AWS side or could not connect. The state machine retries it."""


class TicketingTransientError(Exception):
    """The ticketing system was rate limited, failed on its side or could not be reached. The state machine
    retries it."""


class TicketingRequestError(Exception):
    """The ticketing system refused the request for a reason a retry will not change. Not retried."""


# botocore's throttling codes (botocore.retries.standard) without LimitExceededException, which some
# services use for hard quotas. Security Hub throttles with LimitExceededException, but answers HTTP 429.
THROTTLING_CODES = frozenset({
    'Throttling', 'ThrottlingException', 'ThrottledException', 'RequestThrottledException',
    'TooManyRequestsException', 'ProvisionedThroughputExceededException', 'TransactionInProgressException',
    'RequestLimitExceeded', 'BandwidthLimitExceeded', 'RequestThrottled', 'SlowDown',
    'PriorRequestNotComplete', 'EC2ThrottledException',
})
TIMEOUT_CODES = frozenset({'RequestTimeout', 'RequestTimeoutException'})


def is_transient_status(status_code):
    """HTTP 429 (rate limited) and 5xx (failed on the server side) are worth retrying."""
    return status_code is not None and (status_code == 429 or 500 <= status_code <= 599)


def is_transient(error):
    """True for an error the state machine should retry."""
    if isinstance(error, AWSTransientError):
        return True
    if isinstance(error, (botocore.exceptions.ConnectionError, botocore.exceptions.HTTPClientError)):
        return True
    if isinstance(error, botocore.exceptions.ClientError):
        code = error.response.get('Error', {}).get('Code')
        status = error.response.get('ResponseMetadata', {}).get('HTTPStatusCode')
        return code in THROTTLING_CODES or code in TIMEOUT_CODES or is_transient_status(status)
    return False


def transient_aws_errors(handler):
    """Decorates a lambda_handler: transient AWS errors leave it as AWSTransientError, all else unchanged."""
    @functools.wraps(handler)
    def wrapper(*args, **kwargs):
        try:
            return handler(*args, **kwargs)
        except AWSTransientError:
            raise
        except Exception as error:
            if is_transient(error):
                raise AWSTransientError(f'{type(error).__name__}: {error}') from error
            raise
    return wrapper
